// auto-cleanup of old session state files.
func isStuckActiveSession(st *session.State) bool {
	if !st.Phase.IsActive() {
		return false
	}
	ref := st.LastInteractionTime
	if ref == nil {
		ref = &st.StartedAt
	}
	return time.Since(*ref) > stalenessThreshold
}

